def v2_swap_adjacent_v8(nums: list) -> list:
    for i in range(0, len(nums) - 1, 2):
        nums[i], nums[i + 1] = nums[i + 1], nums[i]
    return nums

def v2_compress_runs_v2(s: str) -> str:
    if not s:
        return ''
    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(s[i - 1] + str(count))
            count = 1
    result.append(s[-1] + str(count))
    return ''.join(result)

def v2_compress_runs_v5(s: str) -> str:
    if not s:
        return ''
    result = s[0]
    count = 1
    for char in s[1:]:
        if char == result[-1]:
            count += 1
        else:
            result += str(count) + char
            count = 1
    return result + str(count)

def v2_rotate_left_v2(nums: list, k: int) -> list:
    n = len(nums)
    if n == 0:
        return []
    k = k % n
    return nums[k:] + nums[:k]

def v2_rotate_left_v6(nums: list, k: int) -> list:
    if not nums:
        return []
    k = k % len(nums)
    return nums[k:] + nums[:k]

def v2_parse_pairs_v1(text: str) -> dict:
    result = {}
    for pair in text.split(','):
        key, value = pair.split('=')
        key = key.strip()
        value = value.strip()
        if key and value.isdigit():
            result[key] = int(value)
    return result

def v2_parse_pairs_v4(text: str) -> dict:
    result = {}
    for pair in text.split(','):
        parts = pair.split('=')
        if len(parts) == 2 and parts[1].strip().isdigit():
            key, value = parts
            result[key.strip()] = int(value.strip())
    return result

