def v2_digit_steps_v4(n: int) -> int:
    if n < 10:
        return 0
    steps = 0
    while n >= 10:
        n = sum(int(digit) for digit in str(n))
        steps += 1
    return steps

def v2_count_pairs_v1(nums: list, target: int) -> int:
    count = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                count += 1
    return count

def v2_count_pairs_v4(nums: list, target: int) -> int:
    count = 0
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            count += seen[complement]
        if num in seen:
            seen[num] += 1
        else:
            seen[num] = 1
    return count

def v2_count_pairs_v8(nums: list, target: int) -> int:
    count = 0
    seen = set()
    for num in nums:
        complement = target - num
        if complement in seen:
            count += seen[complement]
        seen.add(num)
    return count

def v2_longest_run_v1(s: str) -> int:
    if not s:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    return max(max_length, current_length)

